package com.fitconnect.notification;

import com.fitconnect.notification.api.*; import com.fitconnect.notification.domain.*; import com.fitconnect.notification.repository.NotificationRepository; import com.fitconnect.notification.service.NotificationService; import org.junit.jupiter.api.*; import org.mockito.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class NotificationServiceTest { @Mock NotificationRepository repo; NotificationService service; @BeforeEach void init(){MockitoAnnotations.openMocks(this);service=new NotificationService(repo);}
 @Test void createsSendsAndLists(){Notification n=new Notification(1L,"john@example.com",NotificationType.BOOKING_CONFIRMATION,"Subject","Content");when(repo.save(any())).thenReturn(n);when(repo.findByUserId(1L)).thenReturn(java.util.List.of(n));when(repo.findByStatus(NotificationStatus.PENDING)).thenReturn(java.util.List.of());assertEquals(NotificationStatus.SENT,service.create(new NotificationRequest(1L,"john@example.com",NotificationType.BOOKING_CONFIRMATION,"Subject","Content")).status());assertEquals(1,service.user(1L).size());assertTrue(service.pending().isEmpty());}
 @Test void retryAndMissing(){Notification n=new Notification(1L,"a@b.fr",NotificationType.BOOKING_REMINDER,"S","C");when(repo.findById(1L)).thenReturn(java.util.Optional.of(n));when(repo.save(any())).thenReturn(n);assertEquals(NotificationStatus.SENT,service.retry(1L).status());when(repo.findById(2L)).thenReturn(java.util.Optional.empty());assertThrows(IllegalArgumentException.class,()->service.retry(2L));}
}
